package com.bn.aliagent.insight.radar; import java.time.*; import java.util.*;
public record ProblemRadar(UUID radarId,String tenantId,String problemType,Map<String,String> dimensions,Instant windowStart,Instant windowEnd,int metricVersion,int thresholdVersion,int aggregateRevision,RadarStatus status,long version){public ProblemRadar{dimensions=Map.copyOf(new TreeMap<>(dimensions));}public static ProblemRadar open(String tenant,String type,Map<String,String> dims,Instant start,Instant end,int metricVersion,int thresholdVersion,int aggregateRevision){return new ProblemRadar(UUID.randomUUID(),tenant,type,dims,start,end,metricVersion,thresholdVersion,aggregateRevision,RadarStatus.OPEN,0);}public ProblemRadar transition(RadarStatus target,String operator,String reason){boolean legal=(status==RadarStatus.OPEN&&(target==RadarStatus.ACKNOWLEDGED||target==RadarStatus.IGNORED))||(status==RadarStatus.ACKNOWLEDGED&&target==RadarStatus.RESOLVED);if(!legal)throw new IllegalStateException("非法雷达状态迁移");return new ProblemRadar(radarId,tenantId,problemType,dimensions,windowStart,windowEnd,metricVersion,thresholdVersion,aggregateRevision,target,version+1);}}
